_RockCommerce.prototype.addProductInfo=function(info){this.productinfos=this.productinfos||[];this.productinfos.push(info)};_RockCommerce.prototype.getProductInfo=function(el){let root=el.closest("[x-data=rcproductinfo]");if(!root)return!1;let infos=this.productinfos||[];let foundInfo=!1;infos.forEach((info)=>{if(info.$el===el){foundInfo=info;return}});return foundInfo};document.addEventListener("alpine:init",()=>{Alpine.data("rcproductinfo",()=>({count:0,min:1,price:0,init(){this.priceEL=this.$el.querySelector("[rc-price]");this.setMin();this.setCount();this.initUpdateUrl();this.updatePrice();this.$watch("count",this.updatePrice.bind(this));this.watchVariations();RockCommerce.addProductInfo(this)},decrement(){if(this.count>this.min)this.count--;else this.count=this.min},increment(){if(this.count<this.min)this.count=this.min;else this.count++},initUpdateUrl(){this.updateUrl=!!this.$el.getAttribute("data-rc-updateurl")},setCount(count){if(!count){let el=this.$el.querySelector("input[x-model=count]");el.addEventListener("focus",el.select);if(!el)return;count=el.value}
if(!count)return;this.count=count},setMin(){this.min=1;let el=this.$el.querySelector("input[x-model=count]");if(!el)return;this.min=el.getAttribute("min")||this.min},updatePrice(){if(!this.price){this.price=RockCommerce.money(this.$el.getAttribute("data-rc-price"))}
if(!this.priceEL)return;this.priceEL.innerText=this.price.multiply(this.count).toFormat()},watchVariations(){document.addEventListener("click",(e)=>{let option=e.target.closest("[rc-variation-option]");if(!option)return;option.classList.toggle("rc-active");e.preventDefault()})},}))})